 'college-report'(){const {co}=current();if(!co?.assessmentId&&!permitted('university'))return card('تقرير الكلية',notice('يجب بدء التقويم الذاتي أولًا قبل إعداد تقرير الكلية.'));const list=card('تقارير الكليات',table(['الكلية','حالة التقرير','المؤشرات','التحقيق','الإجراء'],collegeRows()));if(!co?.assessmentId)return list;return list+`<div class="grid grid-2" style="margin-top:20px">`+card('تقرير '+esc(name(cx.collegeId)),badge(co.status)+`<p>الأدلة: ${co.evidence.length} · المعتمدة: ${co.evidence.filter(e=>e.status==='معتمد').length}</p>`+area('reportNote','ملاحظات التقرير',co.note,permitted('college')&&co.editable?'':'disabled')+`<p>ملاحظات العميد: ${esc(co.reviewNote)}</p><div class="quick-actions">${permitted('college','dean')?btn('تنزيل ملف تقرير الكلية Word','role-report','college','secondary'):''}${permitted('college')&&co.editable?btn('حفظ المسودة','college-draft')+btn('إرسال للعميد','college-submit'):''}${permitted('dean')&&co.status==='بانتظار مراجعة العميد'?btn('مراجعة واتخاذ قرار','college-review'):''}</div>`)+card('تاريخ التقرير',history(co))+'</div>';},
 'university-report'(){const {f}=current();const rows=table(['الكلية','حالة التقرير','المؤشرات','التحقيق'],collegeRows());if(!f.reportId)return card('التقرير الجامعي — '+esc(name(cx.universityId)),rows+notice('يُنشأ التقرير بعد اعتماد تقارير جميع الكليات المشاركة.')+(permitted('university')?btn('تجميع وإنشاء التقرير','generate-university-report',cx.cycleId):''));const can=permitted('university')&&f.editable;return card('التقرير الجامعي — '+esc(name(cx.universityId)),rows+`<p>${badge(f.status)} · النتيجة المجمعة: ${f.overallScore}% · عدد الكليات: ${f.collegeCount}</p>`+area('universitySummary','الملخص التنفيذي',f.note,can?'':'disabled')+area('universityRecommendations','التوصيات',f.recommendations,can?'':'disabled')+`<p>ملاحظات الإدارة المركزية: ${esc(f.reviewNote)}</p><div class="quick-actions">${btn('تنزيل ملف التقرير الجامعي Word','word','','secondary')}${can?btn('حفظ المسودة','university-draft')+btn('إرسال للإدارة المركزية','university-submit'):''}${permitted('central')&&f.status==='بانتظار الإدارة المركزية'?btn('مراجعة التقرير','university-review'):''}</div>`+history(f));},
