 'external-report'(){const {f}=current(),ex=f.external,team=state.teams.find(t=>t.cycleId===cx.cycleId&&t.universityId===cx.universityId),can=permitted('evaluator')&&ex.editable;if(!ex.evaluationId)return card('التقرير الخارجي',notice('بعد اعتماد التقرير الجامعي، كوّن فريقًا وأكمل زيارة ميدانية ثم ابدأ التكليف.'),permitted('central')&&team?btn('بدء تكليف التقييم الخارجي','assign-external',team.id):'');return card('التقرير الخارجي',badge(ex.status)+area('strengths','نقاط القوة',ex.strengths,can?'':'disabled')+area('weaknesses','نقاط الضعف',ex.weaknesses,can?'':'disabled')+area('recommendations','التوصيات',ex.recommendations,can?'':'disabled')+`<div class="quick-actions">${permitted('evaluator','central')?btn('تنزيل ملف التقرير الخارجي Word','role-report','external','secondary'):''}${can?btn('حفظ مسودة','external-draft')+btn('إرسال للمراجعة','external-submit'):''}${permitted('central')&&ex.status==='بانتظار الإدارة المركزية'?btn('مراجعة التقرير','external-review'):''}</div>`+history(ex));},
 gaps(){const {cy,f,cols}=current();return card('مقارنة التقويم الذاتي بالتقييم الخارجي',notice('الفجوة = الخارجي − الذاتي. التصنيف حسب القيمة المطلقة: عالية ≥ 1، متوسطة ≥ 0.5، بسيطة أقل من ذلك.')+table(['الكلية','المؤشر','الذاتي','الخارجي','الفجوة','التصنيف'],cols.flatMap(c=>cy.standards.indicators.map(i=>{const a=Q.cf(state,cx.cycleId,c).scores[i.id],b=f.external.scores[c+'|'+i.id],g=Number.isFinite(a)&&Number.isFinite(b)?b-a:null;return [esc(name(c)),esc(i.text),a??'—',b??'—',g??'غير مكتمل',g===null?'—':badge(Math.abs(g)>=1?'عالية':Math.abs(g)>=.5?'متوسطة':'بسيطة')];}))));},
