 accreditation(){const {f}=current(),a=f.accreditation,ex=f.external,canSubmit=permitted('university')&&!a.requestId&&ex.status==='معتمد';return `<div class="grid grid-2">`+card('طلب الاعتماد',notice('يُقدّم الطلب من تقرير خارجي معتمد وخطة تحسين مكتملة.')+`<p>التقييم الخارجي: ${badge(ex.status)}</p>`+area('accreditationNote','مبررات طلب الاعتماد',a.note,canSubmit?'required':'disabled')+(canSubmit?btn('تقديم طلب الاعتماد','accreditation-submit'):''))+card('حالة الطلب والقرار',badge(a.status||'لم يرسل')+`<p>${esc(a.note||'لا يوجد طلب مقدم.')}</p>${a.decisionNumber?`<p>رقم القرار: ${esc(a.decisionNumber)} · ${esc(a.decisionType)}</p>`:''}`+(permitted('central')&&a.status==='قيد المراجعة'?btn('تسجيل قرار الجهة المختصة','accreditation-decision'):''));},
 reports(){const {cols,f}=current(),data=state.serverReports||{rows:[],summary:{}};const rows=data.rows.filter(x=>x.cycleId===cx.cycleId&&x.universityId===cx.universityId);const s=data.summary||{};return `<div class="grid grid-4 status-grid">${[['جامعات ضمن التقرير',s.universities||0],['تقييمات خارجية معتمدة',s.approvedExternal||0],['قرارات اعتماد صادرة',s.decisions||0],['إجراءات تحسين مكتملة',(s.completedActions||0)+' / '+(s.actions||0)]].map(([l,v])=>`<div class="stat"><div class="label">${l}</div><div class="value">${v}</div></div>`).join('')}</div><div class="page-tools">${btn('طباعة / حفظ PDF','print')}${btn('تصدير CSV لبرنامج Excel','csv','','secondary')}${btn('تصدير تقرير Word','word','','secondary')}</div>`+card('ملخص الجامعة والدورة',table(['الجامعة','الكليات المعتمدة','الخارجي','درجة الخارجي','التحسين','الاعتماد'],rows.map(x=>[esc(name(x.universityId)),x.approvedColleges+' / '+x.collegeCount,badge(x.externalStatus==='approved'?'معتمد':x.externalStatus||'غير مكتمل'),x.externalScore||'—',x.completedActions+' / '+x.actions,x.decision?esc(x.decision+' · '+x.decisionNumber):'—'])))+card('نتائج الكليات',table(['الكلية','التقويم الذاتي','التقييم الخارجي','حالة التقرير'],cols.map(c=>[esc(name(c)),result(c),result(c,true),badge(Q.cf(state,cx.cycleId,c).status)]))+`<p>التقرير الجامعي: ${badge(f.status)} · التقرير الخارجي: ${badge(f.external.status)} · الاعتماد: ${badge(f.accreditation.status)}</p>`);},
